beforeExample:
package test;
import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;

interface AbstractInlinedAnnotation { int getHeight(); }

class Example {
    void foo(GC gc, StyledText textWidget, int x, int y, Rectangle client, AbstractInlinedAnnotation annotation) {
        textWidget.drawBackground(gc, x, y, client.width, annotation.getHeight());
    }
}

